#include <format>
#include <iostream>
#include <string_view>
#include <vector>

// A profile of one simulation, in wall milliseconds. Two of the three costs are paid once per
// step, so they shrink when the step grows; the sensors are paid at their own rate, so they do
// not. Replace these three numbers with ones measured on your machine: the point is the shape.
struct Profile {
  double physics_ms_per_step;
  double transport_ms_per_step;
  double sensors_ms_per_second;  // at the sensor rates the world asks for
};

[[nodiscard]] double wall_ms_per_simulated_second(Profile profile, double step_ms) {
  const double steps = 1000.0 / step_ms;
  return steps * (profile.physics_ms_per_step + profile.transport_ms_per_step) + profile.sensors_ms_per_second;
}

[[nodiscard]] double factor(Profile profile, double step_ms) {
  return 1000.0 / wall_ms_per_simulated_second(profile, step_ms);
}

struct Lever {
  std::string_view name;
  Profile profile;
  double step_ms;
};

int main() {
  constexpr Profile measured{
      .physics_ms_per_step = 0.42, .transport_ms_per_step = 0.16, .sensors_ms_per_second = 620.0};
  constexpr double step_ms = 1.0;

  const double steps = 1000.0 / step_ms;
  const double physics = steps * measured.physics_ms_per_step;
  const double transport = steps * measured.transport_ms_per_step;
  const double total = wall_ms_per_simulated_second(measured, step_ms);

  std::cout << std::format("per simulated second at a {:.0f} ms step, in wall milliseconds\n", step_ms);
  std::cout << std::format("  physics    {:>7.0f}  {:>5.1f}%\n", physics, 100.0 * physics / total);
  std::cout << std::format("  sensors    {:>7.0f}  {:>5.1f}%\n", measured.sensors_ms_per_second,
                           100.0 * measured.sensors_ms_per_second / total);
  std::cout << std::format("  transport  {:>7.0f}  {:>5.1f}%\n", transport, 100.0 * transport / total);
  std::cout << std::format("  total      {:>7.0f}  real-time factor {:.2f}\n\n", total, factor(measured, step_ms));

  const Profile no_transport{.physics_ms_per_step = measured.physics_ms_per_step,
                             .transport_ms_per_step = 0.0,
                             .sensors_ms_per_second = measured.sensors_ms_per_second};
  const Profile fast_physics{.physics_ms_per_step = measured.physics_ms_per_step / 2.0,
                             .transport_ms_per_step = measured.transport_ms_per_step,
                             .sensors_ms_per_second = measured.sensors_ms_per_second};
  const Profile half_sensors{.physics_ms_per_step = measured.physics_ms_per_step,
                             .transport_ms_per_step = measured.transport_ms_per_step,
                             .sensors_ms_per_second = measured.sensors_ms_per_second / 2.0};

  std::cout << std::format("{:<34} {:>7}\n", "one change at a time", "factor");
  for (const Lever& lever : std::vector<Lever>{
           {.name = "nothing changed", .profile = measured, .step_ms = 1.0},
           {.name = "transport removed entirely", .profile = no_transport, .step_ms = 1.0},
           {.name = "physics twice as fast", .profile = fast_physics, .step_ms = 1.0},
           {.name = "sensor rates halved", .profile = half_sensors, .step_ms = 1.0},
           {.name = "step 1 ms to 2 ms", .profile = measured, .step_ms = 2.0},
           {.name = "step 1 ms to 4 ms", .profile = measured, .step_ms = 4.0},
           {.name = "step 4 ms and sensor rates halved", .profile = half_sensors, .step_ms = 4.0}}) {
    std::cout << std::format("{:<34} {:>7.2f}\n", lever.name, factor(lever.profile, lever.step_ms));
  }
}
